// AI generated by: Claude Code / claude-opus-5-5
// Prompt: "Adopt and discard in the editor"
// Changes: Adopt dialog – a native <dialog> opened with showModal() (the ConfirmDialog pattern: named by its heading,
//          Esc / Cancel close it, focus returns to the trigger). A <fieldset> of real checkboxes, one per part:
//          unchanged parts are disabled with the text "bez zmien", parts changed on both sides start unticked with a
//          warning tied to their checkbox, adopting the definition without the grammar rules (or vice versa) warns.
//          The changes are computed against the freshest project it has; when adoption is refused as stale the
//          parent hands in the fresh project, the choices are recomputed and a notice says so.

// AI generated by: Claude Code / claude-opus-5-5
// Prompt: "Spec #1 review fixes"
// Changes: A part changed only in the project is shown as unchanged in the draft (not tickable), with its own note.
import { useEffect, useId, useMemo, useRef, useState, type FormEvent } from 'react'
import { adoptChoices, initialSelection, pairingWarning } from '#/lib/adoption'
import { draftChanges } from '#/lib/changes'
import { PART_LABELS } from '#/lib/drafts'
import { PARTS, readParts, type PartName, type Parts } from '#/lib/parts'
import type { ProjectRecord } from '#/server/projects.server'
import { PrimaryButton, Button, cx } from './ui'

export interface AdoptDialogProps {
  label: string
  /** The draft's parts as the editor shows them. */
  draft: Parts
  /** The draft's fork point (for "changed on both sides"). */
  base: Parts
  /** The freshest project known; its revision is the one the human decides on. */
  project: ProjectRecord
  /** The project moved since the dialog opened (the last attempt was refused); show a notice. */
  refreshed: boolean
  /** Adopt the chosen parts; resolves when done (the parent closes the dialog) or refused (fresh project handed in). */
  onAdopt: (parts: PartName[], projectRevision: number) => Promise<void>
  onClose: () => void
}

export function AdoptDialog({ label, draft, base, project, refreshed, onAdopt, onClose }: AdoptDialogProps) {
  const dialogRef = useRef<HTMLDialogElement>(null)
  const formRef = useRef<HTMLFormElement>(null)
  const id = useId()
  const choices = useMemo(() => adoptChoices(draftChanges({ draft, project: readParts(project.data), base })), [draft, project, base])
  const [selected, setSelected] = useState<PartName[]>(() => initialSelection(choices))
  const [busy, setBusy] = useState(false)
  // A fresh project after a refusal: start over from its defaults.
  const [shownRevision, setShownRevision] = useState(project.revision)
  if (shownRevision !== project.revision) {
    setShownRevision(project.revision)
    setSelected(initialSelection(choices))
  }

  useEffect(() => {
    const dialog = dialogRef.current
    if (dialog && !dialog.open) dialog.showModal()
    // React does not render autofocus for showModal(): focus the first part that can be ticked (or Cancel).
    const first = formRef.current?.querySelector<HTMLElement>('input:not(:disabled)') ?? formRef.current?.querySelector<HTMLElement>('button')
    first?.focus()
  }, [])

  const warning = pairingWarning(choices, selected)
  const nothing = PARTS.every((part) => !choices[part].selectable)
  const toggle = (part: PartName, on: boolean) =>
    setSelected((prev) => PARTS.filter((p) => (p === part ? on : prev.includes(p))))

  const submit = async (e: FormEvent) => {
    e.preventDefault()
    if (busy || !selected.length) return
    setBusy(true)
    try {
      await onAdopt(selected, project.revision)
    } finally {
      setBusy(false)
    }
  }

  const titleId = `${id}-title`
  const introId = `${id}-intro`
  const warningId = `${id}-pairing`
  const noteId = (part: PartName) => `${id}-${part}`

  return (
    <dialog
      ref={dialogRef}
      aria-labelledby={titleId}
      aria-describedby={introId}
      onClose={onClose}
      onCancel={(e) => busy && e.preventDefault()}
      className="app-dialog m-auto w-[min(34rem,calc(100vw-2rem))] rounded-2xl border border-white/10 bg-surface p-5 text-zinc-100 shadow-2xl"
    >
      <h2 id={titleId} className="text-base font-semibold text-zinc-50 [overflow-wrap:anywhere]">
        Prevziať návrh „{label}“ do projektu
      </h2>
      <p id={introId} className="mt-2 text-sm leading-relaxed text-zinc-300">
        Vybrané časti prepíšu tie isté časti projektu. Pred prevzatím sa stav projektu uloží do jeho histórie ako
        bezpečnostná záloha, takže sa prevzatie dá vrátiť. Návrh sa potom ukončí.
      </p>
      {refreshed && (
        <p role="alert" className="mt-3 rounded-lg border border-amber-400/40 bg-amber-500/10 px-3 py-2 text-sm text-amber-100">
          Projekt sa medzitým zmenil (revízia {project.revision}), preto sa nič neprevzalo. Výber je prepočítaný podľa
          aktuálneho projektu – skontroluj ho a potvrď znova.
        </p>
      )}
      <form ref={formRef} onSubmit={(e) => void submit(e)} className="mt-4">
        <fieldset disabled={busy}>
          <legend className="mb-2 text-xs font-medium tracking-wide text-zinc-400 uppercase">Časti na prevzatie</legend>
          <ul className="flex flex-col gap-2">
            {PARTS.map((part) => {
              const choice = choices[part]
              const pairs = part === 'definition' || part === 'grammarRules'
              const describedBy = [noteId(part), pairs && warning ? warningId : null].filter(Boolean).join(' ')
              return (
                <li key={part} className={cx('rounded-lg border px-3 py-2', choice.bothSides ? 'border-amber-400/40' : 'border-white/10')}>
                  <div className="flex items-center gap-2">
                    <input
                      type="checkbox"
                      id={`${id}-cb-${part}`}
                      checked={selected.includes(part)}
                      disabled={!choice.selectable}
                      onChange={(e) => toggle(part, e.target.checked)}
                      aria-describedby={describedBy}
                      className="m-0 size-4 accent-indigo-400"
                    />
                    <label htmlFor={`${id}-cb-${part}`} className={cx('text-sm', choice.selectable ? 'text-zinc-100' : 'text-zinc-500')}>
                      {PART_LABELS[part]}
                    </label>
                  </div>
                  <p id={noteId(part)} className={cx('mt-0.5 pl-6 text-xs', choice.bothSides ? 'font-medium text-amber-200' : 'text-zinc-400')}>
                    {choice.projectOnly
                      ? 'Bez zmien v návrhu – túto časť medzitým zmenil projekt. Jeho novšia verzia zostane.'
                      : !choice.selectable
                        ? 'Bez zmien – rovnaká ako v projekte.'
                        : choice.bothSides
                          ? '⚠ Zmenené na oboch stranách: projekt túto časť od vytvorenia návrhu tiež zmenil. Prevzatím sa jeho zmena prepíše.'
                          : 'Zmenená v návrhu.'}
                  </p>
                </li>
              )
            })}
          </ul>
        </fieldset>
        {/* Space kept so the buttons do not move when the warning appears. */}
        <p id={warningId} className={cx('mt-3 min-h-10 text-sm text-amber-200', !warning && 'invisible')} aria-live="polite">
          {warning && `⚠ ${warning}`}
        </p>
        {nothing && <p className="mt-2 text-sm text-zinc-400">Návrh nemení nič, čo by sa dalo prevziať.</p>}
        <div className="mt-4 flex flex-wrap justify-end gap-2">
          <Button type="button" onClick={() => dialogRef.current?.close()} disabled={busy}>
            Zrušiť
          </Button>
          <PrimaryButton type="submit" disabled={busy || !selected.length}>
            {busy ? 'Preberám…' : `Prevziať vybrané (${selected.length})`}
          </PrimaryButton>
        </div>
      </form>
    </dialog>
  )
}
